<script setup lang="ts">
import {useHysControlState} from '../../composables/formContext'

import {ref,watch,onActivated,onDeactivated,onBeforeUnmount} from 'vue'
import {CloudUpload,FileText,X} from 'lucide-vue-next'
import {useHysRootAttrs} from '../../config'
export interface HysUploadFile {uid:string;name:string;size:number;raw:File}
const props=withDefaults(defineProps<{accept?:string;multiple?:boolean;disabled?:boolean;limit?:number;maxSize?:number;drag?:boolean;showFileList?:boolean;beforeUpload?:(file:File)=>boolean|void|Promise<boolean|void>}>(),{multiple:true,drag:true,showFileList:true})
const {disabled:controlDisabled}=useHysControlState(props)

const emit=defineEmits<{change:[files:HysUploadFile[]];remove:[file:HysUploadFile];exceed:[files:File[]];error:[message:string];select:[files:File[]]}>(),hysRootAttrs=useHysRootAttrs(),files=ref<HysUploadFile[]>([]),input=ref<HTMLInputElement>(),dragging=ref(false),busy=ref(false)
function accepted(file:File){return !props.accept||props.accept.split(',').some(rule=>{rule=rule.trim().toLowerCase();return rule.startsWith('.')?file.name.toLowerCase().endsWith(rule):rule.endsWith('/*')?file.type.startsWith(rule.slice(0,-1)):file.type===rule})}
let generation=0,active=true
function invalidate(){generation++;busy.value=false;dragging.value=false;if(input.value)input.value.value=''}
watch(()=>controlDisabled.value,invalidate);onActivated(()=>{active=true});onDeactivated(()=>{active=false;invalidate()});onBeforeUnmount(()=>{active=false;invalidate()})
async function add(list:File[]){if(!active||controlDisabled.value||busy.value)return;if(!props.multiple)list=list.slice(0,1);if(props.limit&&(props.multiple?files.value.length:0)+list.length>props.limit){emit('exceed',list);return}const token=++generation;busy.value=true;const result:HysUploadFile[]=[];try{for(const file of list){if(!active||token!==generation||controlDisabled.value)return;try{if(!accepted(file)){emit('error','文件类型不符合要求：'+file.name);continue}if(props.maxSize&&file.size>props.maxSize){emit('error','文件超过大小限制：'+file.name);continue}if(props.beforeUpload&&await props.beforeUpload(file)===false)continue;if(!active||token!==generation||controlDisabled.value)return;result.push({uid:crypto.randomUUID(),name:file.name,size:file.size,raw:file})}catch(error){if(active&&token===generation)emit('error',error instanceof Error?error.message:'文件检查失败')}}if(!active||token!==generation||controlDisabled.value||!result.length)return;files.value=props.multiple?[...files.value,...result]:result;if(result.length){emit('select',result.map(x=>x.raw));emit('change',[...files.value])}}finally{if(token===generation){busy.value=false;if(input.value)input.value.value=''}}}
function remove(file:HysUploadFile){if(controlDisabled.value)return;files.value=files.value.filter(x=>x.uid!==file.uid);emit('remove',file);emit('change',[...files.value])}
defineExpose({clearFiles:()=>{invalidate();files.value=[];emit('change',[])},open:()=>{if(active&&!controlDisabled.value&&!busy.value)input.value?.click()}})
</script>
<template><div v-bind="hysRootAttrs"><div class="hys-ui-upload-zone" :class="{'hys-ui-upload-dragging':dragging}" role="button" :aria-disabled="controlDisabled||busy" :tabindex="controlDisabled?-1:0" aria-label="选择上传文件" @click="!controlDisabled&&input?.click()" @keydown.enter.prevent="!controlDisabled&&input?.click()" @keydown.space.prevent="!controlDisabled&&input?.click()" @dragover.prevent="drag&&!controlDisabled&&(dragging=true)" @dragleave="dragging=false" @drop.prevent="dragging=false;drag&&add(Array.from($event.dataTransfer?.files||[]))"><slot><CloudUpload :size="28" aria-hidden="true"/><strong>{{busy?'正在检查文件…':'点击选择或拖入文件'}}</strong><span>文件通过事件交给业务层上传</span></slot></div><input ref="input" hidden type="file" :accept="accept" :multiple="multiple" :disabled="controlDisabled||busy" @change="add(Array.from(($event.target as HTMLInputElement).files||[]))"/><div v-if="showFileList"><div v-for="file in files" :key="file.uid" class="hys-ui-upload-file"><FileText :size="16"/><slot name="file" :file="file">{{file.name}}</slot><button type="button" :aria-label="'移除'+file.name" :disabled="controlDisabled" @click="remove(file)"><X :size="14"/></button></div></div></div></template>
<style scoped>.hys-ui-upload-zone[aria-disabled=true]{opacity:.5;cursor:not-allowed}.hys-ui-upload-dragging{background:var(--hys-ui-primary-soft,var(--hys-ui-theme-primary-soft));border-style:solid}</style>
